inline const CgtCategoryPrior& lookup_cgt_prior(std::string_view id) {
    const auto& all = get_cgtrader_learned_priors();
    for (const auto& p : all) if (id == p.id) return p;
    return all.front();
}

inline float eval_cgt_learned_silhouette(const CgtCategoryPrior& p, float u) {
    float val = p.harmonic_w[0];
    for (int k = 1; k <= 7; ++k) {
        float ang = static_cast<float>(k) * 3.14159265f * u;
        val += p.harmonic_w[2 * k - 1] * std::cos(ang) + p.harmonic_w[2 * k] * std::sin(ang);
    }
    return val < 0.015f ? 0.015f : val;
}

